    """Return the order total after applying a percentage discount.

    discount_percent is a percentage and must be within 0..100 inclusive;
    any invalid value raises ValueError.
    """
    if isinstance(discount_percent, bool) or not isinstance(discount_percent, (int, float)):
        raise ValueError("discount_percent must be a number between 0 and 100")
    if not (0 <= discount_percent <= 100):
        raise ValueError("discount_percent must be between 0 and 100 inclusive")

    subtotal = sum(prices)
    return subtotal - subtotal * discount_percent / 100
